import java.util.*;

class Solution {
  public ListNode reverseEvenLengthGroups(ListNode head) {
    ListNode dummy = new ListNode(0, head), prev = dummy, cur = head;
    int size = 1;
    while (cur != null) {
      ListNode end = cur;
      int len = 0;
      while (end != null && len < size) {
        end = end.next;
        len++;
      }
      if ((len & 1) == 0) {
        ListNode p = end, node = cur;
        for (int i = 0; i < len; i++) {
          ListNode next = node.next;
          node.next = p;
          p = node;
          node = next;
        }
        prev.next = p;
        prev = cur;
      } else {
        for (int i = 0; i < len; i++) prev = prev.next;
      }
      cur = end;
      size++;
    }
    return dummy.next;
  }
}
